DROP TABLE IF EXISTS career_paths;
CREATE TABLE career_paths (
    id text PRIMARY KEY,
    name text NOT NULL,
    domain text NOT NULL,
    skills jsonb NOT NULL,
    subjects jsonb NOT NULL,
    work_style jsonb NOT NULL,
    description text NOT NULL,
    education jsonb NOT NULL,
    paths jsonb NOT NULL,
    growth text NOT NULL,
    salary_range text NOT NULL,
    entrance jsonb NOT NULL,
    roadmap_sequence jsonb NOT NULL
); 
CREATE INDEX idx_career_paths_domain ON career_paths(domain);

INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('data-analyst', 'Data Analyst', 'Technology', '["Statistical reasoning", "Data visualization", "Query writing"]', '["Mathematics", "Computer Science"]', '["Pattern-spotting in numbers", "Working independently"]', 'Analyze data to help organizations make better decisions.', '["B.Sc./B.Tech in Statistics, Mathematics, or Computer Science", "Certifications in Data Analytics or SQL"]', '["Learn statistics and SQL basics", "Master a BI tool (Excel/Power BI/Tableau)", "Build a portfolio of real-data projects", "Apply for entry-level analyst roles"]', 'High', '₹2–14 LPA', '["No standardized entrance exam; admission via university-specific undergraduate criteria (12th-grade marks/JEE for some B.Tech programs)"]', '[{"title": "Statistics & Math Foundations", "description": "Learn descriptive and inferential statistics."}, {"title": "Excel & Spreadsheets", "description": "Master data manipulation in spreadsheets."}, {"title": "SQL", "description": "Learn to query and join relational databases."}, {"title": "Data Visualization", "description": "Build dashboards using Power BI or Tableau."}, {"title": "Python for Data", "description": "Use pandas and numpy for analysis."}, {"title": "Portfolio Project", "description": "Analyze a real public dataset end-to-end."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('ml-engineer', 'Machine Learning Engineer', 'Technology', '["Algorithm design", "Model tuning", "Statistical reasoning"]', '["Mathematics", "Computer Science"]', '["Iterative experimentation", "Working independently"]', 'Design and build AI models that learn from data.', '["B.Tech/B.Sc. in Computer Science, Mathematics, or Statistics", "Specialization in ML/AI via courses or Master''s"]', '["Learn Python and math foundations", "Study core ML algorithms", "Build and deploy models", "Contribute to open-source or internships"]', 'High', '₹3.5–24 LPA', '["JEE Main/Advanced or state engineering entrance exams for B.Tech admission"]', '[{"title": "Python Programming", "description": "Get comfortable writing and debugging Python code."}, {"title": "Linear Algebra & Probability", "description": "Build the math foundation ML relies on."}, {"title": "Core ML Algorithms", "description": "Learn regression, classification, and clustering."}, {"title": "Deep Learning Basics", "description": "Understand neural networks and frameworks like PyTorch."}, {"title": "Model Deployment", "description": "Learn to serve models via APIs."}, {"title": "Capstone Project", "description": "Build and deploy an end-to-end ML application."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('software-engineer', 'Software Engineer', 'Technology', '["System design", "Debugging", "Code structuring"]', '["Computer Science", "Mathematics"]', '["Building systematically", "Collaborative building"]', 'Design software, systems, and digital products that solve real problems.', '["B.Tech/B.E. in Computer Science or related field", "Bootcamps or self-taught paths are also common entry routes"]', '["Learn a programming language deeply", "Study data structures and algorithms", "Build personal projects", "Contribute to open source, then apply for internships"]', 'High', '₹3–18 LPA', '["JEE Main/Advanced or state engineering entrance exams for B.Tech admission"]', '[{"title": "Programming Fundamentals", "description": "Learn a language like Python, Java, or JavaScript."}, {"title": "Data Structures & Algorithms", "description": "Master core CS problem-solving patterns."}, {"title": "Version Control (Git)", "description": "Learn collaborative code management."}, {"title": "Web or App Development", "description": "Build a full-stack project end-to-end."}, {"title": "System Design Basics", "description": "Understand how larger systems are structured."}, {"title": "Portfolio & Open Source", "description": "Contribute to real projects to build credibility."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('blockchain-dev', 'Blockchain Developer', 'Technology', '["Cryptographic logic", "Smart contract design", "Debugging"]', '["Computer Science", "Mathematics"]', '["Building systematically", "Working independently"]', 'Build decentralized applications and smart contracts.', '["B.Tech/B.Sc. in Computer Science", "Specialized blockchain/Web3 certification courses"]', '["Learn programming and cryptography basics", "Learn Solidity or a smart contract language", "Build and deploy test contracts", "Contribute to Web3 projects"]', 'Variable', '₹2–20 LPA', '["JEE Main/Advanced or state engineering entrance exams for B.Tech admission"]', '[{"title": "Programming Foundations", "description": "Get solid in JavaScript or Python first."}, {"title": "Blockchain Fundamentals", "description": "Understand how distributed ledgers work."}, {"title": "Solidity Basics", "description": "Learn to write smart contracts."}, {"title": "Testing & Security", "description": "Learn common vulnerabilities and how to avoid them."}, {"title": "Build a dApp", "description": "Create a decentralized application end-to-end."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('ethical-hacker', 'Ethical Hacker / Cybersecurity Analyst', 'Technology', '["Vulnerability tracing", "Adversarial thinking", "Attention to detail"]', '["Computer Science", "Mathematics"]', '["Systematic investigation", "Working independently"]', 'Secure computer systems by finding and fixing vulnerabilities.', '["B.Tech/B.Sc. in Computer Science or IT", "Certifications like CEH, OSCP (post-graduation)"]', '["Learn networking and OS fundamentals", "Practice on lab environments (CTFs)", "Learn common attack/defense techniques", "Earn a recognized certification"]', 'High', '₹3–14.6 LPA', '["JEE Main/Advanced or state engineering entrance exams for B.Tech admission"]', '[{"title": "Networking Basics", "description": "Understand how systems communicate."}, {"title": "Operating Systems", "description": "Learn Linux and Windows internals."}, {"title": "Capture The Flag Practice", "description": "Solve beginner security challenges."}, {"title": "Web App Security", "description": "Learn common vulnerabilities (OWASP Top 10)."}, {"title": "Certification Prep", "description": "Prepare for an entry-level security certification."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
