INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('mobile-dev', 'Mobile App Developer', 'Technology', '["Interface coding", "Debugging", "User-flow thinking"]', '["Computer Science"]', '["Building systematically", "Iterative experimentation"]', 'Build mobile applications for iOS and Android platforms.', '["B.Tech/B.Sc. in Computer Science", "Self-taught or bootcamp routes are common"]', '["Learn a mobile framework", "Build small apps", "Publish an app to a store", "Apply for junior developer roles"]', 'High', '₹1.7–19 LPA', '["JEE Main/Advanced or state engineering entrance exams for B.Tech admission"]', '[{"title": "Programming Fundamentals", "description": "Learn Kotlin, Swift, or a cross-platform language."}, {"title": "Mobile Framework", "description": "Pick React Native, Flutter, or native SDKs."}, {"title": "UI Building", "description": "Learn mobile-specific design patterns."}, {"title": "App Publishing", "description": "Ship an app to the Play Store or App Store."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
