VALUES ('dba', 'Database Administrator', 'Technology', '["Structured data modeling", "Reliability planning", "Attention to detail"]', '["Computer Science", "Mathematics"]', '["Working independently", "Building systematically"]', 'Manage and maintain the databases that power applications and organizations.', '["B.Tech/B.Sc. in Computer Science or IT", "Database certifications (Oracle, MySQL, etc.)"]', '["Learn SQL deeply", "Understand database design principles", "Practice performance tuning", "Earn a database certification"]', 'Moderate', '₹3.3–17 LPA', '["JEE Main/Advanced or state engineering entrance exams for B.Tech admission"]', '[{"title": "SQL Mastery", "description": "Go beyond basics into optimization and joins."}, {"title": "Database Design", "description": "Learn normalization and schema design."}, {"title": "Backup & Recovery", "description": "Understand reliability and disaster recovery."}, {"title": "Performance Tuning", "description": "Learn to diagnose and fix slow queries."}]');
