VALUES ('product-manager', 'Product Manager', 'Business', '["Prioritization", "Stakeholder translation", "Roadmap sequencing"]', '["Business Studies", "Economics"]', '["Coordinating across teams", "Structured problem solving"]', 'Decide what products should solve, for whom, and how teams should build them.', '["Any bachelor''s degree; often paired with an MBA", "PM-specific certifications are increasingly common"]', '["Learn product fundamentals and frameworks", "Work in a related role (engineering, design, or business)", "Practice writing specs and prioritizing features", "Move into an associate PM role"]', 'Moderate', '₹6.7–40 LPA', '["No standardized entrance exam; typically entered via engineering/business degree plus CAT/GMAT for MBA route"]', '[{"title": "Product Fundamentals", "description": "Learn how products get built and shipped."}, {"title": "User Research Basics", "description": "Learn to understand real user needs."}, {"title": "Prioritization Frameworks", "description": "Learn to decide what to build first."}, {"title": "Case Study Practice", "description": "Practice mock PM interview case studies."}]');
