VALUES ('operations-manager', 'Operations Manager', 'Business', '["Process optimization", "Resource allocation", "Prioritization"]', '["Business Studies", "Mathematics"]', '["Structured problem solving", "Coordinating across teams"]', 'Oversee day-to-day processes to keep an organization running efficiently.', '["Bachelor''s in Business, Engineering, or related field", "MBA is common for advancement"]', '["Learn process and operations fundamentals", "Work in an operational or coordination role", "Practice process optimization", "Move into operations management"]', 'High', '₹3.3–22.5 LPA', '["CAT, XAT, or CMAT for MBA; undergraduate business programs vary by university"]', '[{"title": "Operations Fundamentals", "description": "Learn how workflows and processes are structured."}, {"title": "Process Mapping", "description": "Learn to visualize and improve workflows."}, {"title": "Resource Planning", "description": "Learn to allocate people, time, and budget."}, {"title": "Metrics & KPIs", "description": "Learn to track and improve operational performance."}]');
