INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('entrepreneur', 'Entrepreneur / Startup Founder', 'Business', '["Opportunity spotting", "Risk assessment", "Resourcefulness"]', '["Business Studies", "Economics"]', '["Iterative experimentation", "Coordinating across teams"]', 'Identify problems worth solving and build a business around the solution.', '["No fixed path; any degree, sometimes none, combined with hands-on experience"]', '["Identify a real problem worth solving", "Validate the idea with real users", "Build a minimum viable product", "Iterate based on feedback and seek funding/traction"]', 'Variable', 'No standardized salary — income can range from ₹0 or losses to very high earnings depending on the business.', '["No entrance exam required; optional CAT/GMAT if pursuing an MBA first"]', '[{"title": "Problem Discovery", "description": "Identify a real, validated problem to solve."}, {"title": "Idea Validation", "description": "Talk to potential users before building."}, {"title": "MVP Building", "description": "Create the smallest viable version of the product."}, {"title": "Iteration & Feedback", "description": "Test, learn, and refine based on real usage."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
