VALUES ('film-director', 'Film Director', 'Media', '["Visual storytelling", "Coordinating across teams", "Creative logic design"]', '["Media Studies", "Art/Design"]', '["Creating visually", "Coordinating across teams"]', 'Oversee the creative and technical execution of a film or video project.', '["Diploma/degree in Film Direction or Mass Communication"]', '["Learn filmmaking fundamentals", "Assist on student or independent productions", "Direct short films", "Build a director''s reel"]', 'Moderate', '₹1.1–15 LPA', '["Institute-specific entrance exams and portfolio/interview rounds (e.g., FTII, SRFTI)"]', '[{"title": "Filmmaking Basics", "description": "Learn story structure, shots, and editing."}, {"title": "On-Set Experience", "description": "Assist on a production in any capacity."}, {"title": "Short Film Project", "description": "Write and direct a short film."}, {"title": "Director''s Reel", "description": "Compile directed work into a showcase reel."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('copywriter', 'Copywriter', 'Media', '["Persuasive writing", "Audience framing", "Concept distillation"]', '["English"]', '["Working independently", "Iterative experimentation"]', 'Write persuasive, clear copy for advertising, branding, and marketing.', '["Bachelor''s in English, Communication, or related field; portfolio matters more than degree"]', '["Learn copywriting fundamentals", "Practice writing for different formats", "Build a portfolio of sample work", "Freelance or apply for junior copywriter roles"]', 'Mixed', '₹2–10.8 LPA', '["No standardized entrance exam; open to graduates from any stream"]', '[{"title": "Copywriting Basics", "description": "Learn persuasive writing structures and tone."}, {"title": "Format Practice", "description": "Write ads, emails, and social copy samples."}, {"title": "Portfolio Building", "description": "Compile a range of polished sample work."}, {"title": "Client/Brief Practice", "description": "Practice responding to real creative briefs."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('pr-specialist', 'Public Relations Specialist', 'Media', '["Narrative framing", "Stakeholder translation", "Crisis response"]', '["English", "Media Studies"]', '["Working with people", "Coordinating across teams"]', 'Manage public image and communication strategy for organizations or individuals.', '["Bachelor''s in Public Relations, Communication, or Journalism"]', '["Complete a communications-related degree", "Intern with a PR agency or in-house team", "Practice media relations and messaging", "Specialize in a sector (corporate, entertainment, etc.)"]', 'High', '₹3–15 LPA', '["CUET or institute-specific entrance exams for communication/PR programs"]', '[{"title": "PR Fundamentals", "description": "Learn messaging, media relations, and reputation basics."}, {"title": "Agency/In-house Internship", "description": "Gain practical PR experience."}, {"title": "Crisis Communication", "description": "Learn to manage sensitive public situations."}, {"title": "Sector Specialization", "description": "Focus on an industry of interest."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('sound-engineer', 'Sound Engineer', 'Media', '["Audio calibration", "Technical listening", "Fine motor precision"]', '["Physics", "Media Studies"]', '["Hands-on building", "Working independently"]', 'Record, mix, and master audio for music, film, and media.', '["Diploma/degree in Audio Engineering or Sound Design"]', '["Learn audio theory and software", "Practice recording and mixing", "Assist in a studio setting", "Build a portfolio of mixed/mastered work"]', 'Moderate', '₹1.5–7.8 LPA', '["Institute-specific entrance exams for audio engineering diplomas/degrees"]', '[{"title": "Audio Fundamentals", "description": "Learn sound theory and signal flow."}, {"title": "DAW Software", "description": "Get skilled in tools like Pro Tools or Ableton."}, {"title": "Studio Assisting", "description": "Gain hands-on studio experience."}, {"title": "Portfolio Project", "description": "Produce a fully mixed and mastered track or scene."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('teacher', 'Teacher / Educator', 'Education', '["Concept simplification", "Behavior coaching", "Lesson sequencing"]', '["English", "Social Science"]', '["Working with people", "Structured problem solving"]', 'Educate and mentor students, shaping how they learn and grow.', '["Bachelor''s degree + B.Ed. (Bachelor of Education)"]', '["Complete a subject-specific bachelor''s degree", "Complete B.Ed. teacher training", "Gain classroom teaching experience", "Pursue specialization or further certification"]', 'High', '₹0.9–5.8 LPA', '["CUET (for undergraduate degree) followed by state/national B.Ed. entrance exams (e.g., state CET)"]', '[{"title": "Subject Expertise", "description": "Build strong knowledge in a teaching subject."}, {"title": "Teacher Training (B.Ed.)", "description": "Learn pedagogy and classroom management."}, {"title": "Classroom Practice", "description": "Gain supervised teaching experience."}, {"title": "Specialization", "description": "Focus on a grade level or teaching method."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
