INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('educational-counselor', 'Educational Counselor', 'Education', '["Active listening", "Behavior coaching", "Case evaluation"]', '["Psychology", "Social Science"]', '["Working with people", "Structured problem solving"]', 'Guide students on academic, career, and personal development decisions.', '["Bachelor''s/Master''s in Psychology or Counseling"]', '["Complete a psychology or counseling degree", "Gain supervised counseling experience", "Learn career guidance frameworks", "Obtain relevant certification if required"]', 'Moderate', '₹2–7 LPA', '["CUET or university-specific entrance exams for psychology/counseling programs"]', '[{"title": "Counseling Foundations", "description": "Learn active listening and guidance principles."}, {"title": "Career Guidance Tools", "description": "Learn frameworks for academic/career advice."}, {"title": "Supervised Practice", "description": "Practice counseling under supervision."}, {"title": "Certification", "description": "Pursue a recognized counseling certification."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('special-ed-specialist', 'Special Education Specialist', 'Education', '["Behavior coaching", "Individualized planning", "Active listening"]', '["Psychology"]', '["Working with people", "Hands-on building"]', 'Support students with learning differences through tailored teaching approaches.', '["Bachelor''s in Special Education or Psychology + specialized diploma"]', '["Complete a special education-focused degree", "Gain hands-on experience with diverse learners", "Learn individualized education planning", "Obtain relevant certification"]', 'High', '₹0.8–5 LPA', '["CUET or institute-specific entrance exams for special education diploma/degree programs"]', '[{"title": "Special Education Foundations", "description": "Learn about diverse learning needs."}, {"title": "Individualized Planning", "description": "Learn to design tailored learning plans."}, {"title": "Practical Experience", "description": "Work directly with students needing support."}, {"title": "Certification", "description": "Pursue a recognized special education certification."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('academic-psychologist', 'Psychologist (Research/Academic)', 'Social Sciences', '["Hypothesis testing", "Behavioral assessment", "Literature synthesis"]', '["Psychology"]', '["Systematic investigation", "Working independently"]', 'Conduct research to understand and explain human behavior and mental processes.', '["B.A./B.Sc. in Psychology", "M.A./M.Phil/Ph.D. for research roles"]', '["Complete undergraduate psychology degree", "Pursue postgraduate research specialization", "Gain research assistant experience", "Publish or present research findings"]', 'Moderate', '₹2.5–8 LPA', '["CUET or university-specific entrance exams for undergraduate psychology"]', '[{"title": "Psychology Foundations", "description": "Build strong theoretical knowledge."}, {"title": "Research Methods", "description": "Learn experimental design and statistics."}, {"title": "Research Assistantship", "description": "Assist on an active research project."}, {"title": "Publication/Presentation", "description": "Contribute to or present a research study."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('social-worker', 'Social Worker', 'Social Sciences', '["Case-building", "Active listening", "Resource navigation"]', '["Social Science", "Psychology"]', '["Working with people", "Coordinating across teams"]', 'Support individuals and communities facing social, economic, or personal challenges.', '["Bachelor''s/Master''s in Social Work (BSW/MSW)"]', '["Complete a social work degree", "Complete supervised fieldwork", "Gain experience with an NGO or community program", "Specialize in a population or issue area"]', 'High', '₹1.5–6 LPA', '["CUET, TISSNET (for TISS), or university-specific exams for BSW/MSW admission"]', '[{"title": "Social Work Foundations", "description": "Learn casework and community intervention basics."}, {"title": "Fieldwork Placement", "description": "Gain supervised hands-on experience."}, {"title": "Specialization", "description": "Focus on an area like child welfare or mental health."}, {"title": "Case Practice", "description": "Take on real casework under guidance."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('sociologist', 'Sociologist', 'Social Sciences', '["Population data analysis", "Fieldwork observation", "Literature synthesis"]', '["Social Science"]', '["Systematic investigation", "Working independently"]', 'Study human society, social relationships, and institutions.', '["B.A. in Sociology", "M.A./Ph.D. for research roles"]', '["Complete a sociology degree", "Learn social research methods", "Conduct fieldwork or survey research", "Pursue postgraduate specialization"]', 'Moderate', '₹3–10 LPA', '["CUET or university-specific entrance exams for undergraduate sociology"]', '[{"title": "Sociology Foundations", "description": "Learn core social theory and concepts."}, {"title": "Research Methods", "description": "Learn surveys, interviews, and data analysis."}, {"title": "Fieldwork Project", "description": "Conduct a small social research study."}, {"title": "Specialization", "description": "Focus on a social issue or institution."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('political-analyst', 'Political Analyst', 'Social Sciences', '["Policy translation", "Population data analysis", "Forecasting"]', '["Political Science", "Economics"]', '["Systematic investigation", "Working independently"]', 'Analyze political systems, policies, and trends to inform decisions or the public.', '["B.A. in Political Science, Economics, or related field", "M.A. for specialized roles"]', '["Complete a political science or related degree", "Learn policy analysis frameworks", "Gain research or internship experience", "Specialize in a policy area or region"]', 'Variable', '₹3–12 LPA', '["CUET or university-specific entrance exams for undergraduate political science/economics"]', '[{"title": "Political Science Foundations", "description": "Learn governance, institutions, and policy basics."}, {"title": "Policy Analysis", "description": "Learn to evaluate policy trade-offs and impact."}, {"title": "Research Internship", "description": "Gain experience with a think tank or research body."}, {"title": "Specialization", "description": "Focus on a specific policy domain."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('anthropologist', 'Anthropologist', 'Social Sciences', '["Fieldwork observation", "Cultural interpretation", "Literature synthesis"]', '["Social Science"]', '["Systematic investigation", "Working with people"]', 'Study human cultures, societies, and their development over time.', '["B.A. in Anthropology", "M.A./Ph.D. for research roles"]', '["Complete an anthropology degree", "Learn ethnographic research methods", "Conduct fieldwork", "Pursue postgraduate specialization"]', 'Stable', '₹3–10 LPA', '["CUET or university-specific entrance exams for undergraduate anthropology"]', '[{"title": "Anthropology Foundations", "description": "Learn cultural and social anthropology basics."}, {"title": "Ethnographic Methods", "description": "Learn observation and interview-based research."}, {"title": "Fieldwork Project", "description": "Conduct a small ethnographic study."}, {"title": "Specialization", "description": "Focus on a cultural, regional, or thematic area."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('musician', 'Musician / Composer', 'Arts', '["Compositional structuring", "Technical listening", "Improvisation"]', '["Art/Design"]', '["Creating visually", "Working independently"]', 'Compose, perform, or produce music across genres and formats.', '["Formal music degree optional; many succeed through independent training"]', '["Learn an instrument or vocal technique deeply", "Study music theory and composition", "Perform or record regularly", "Build an audience or professional network"]', 'Variable', 'No standardized salary — earnings vary widely by employment, freelance work, performances, royalties and commissions.', '["No standardized entrance exam; some institutes (e.g., music colleges) hold audition-based admissions"]', '[{"title": "Instrument/Voice Training", "description": "Build strong technical performance skills."}, {"title": "Music Theory", "description": "Learn composition and harmony fundamentals."}, {"title": "Performance Practice", "description": "Perform regularly to build experience."}, {"title": "Recording/Portfolio", "description": "Produce recorded work to share or perform."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('actor', 'Actor', 'Arts', '["Emotional expression", "Improvisation", "Memorization"]', '["Art/Design"]', '["Working with people", "Creating visually"]', 'Portray characters in film, television, or theatre.', '["Formal acting training optional; drama school or workshops help"]', '["Train in acting technique", "Perform in theatre or student productions", "Build a demo reel", "Audition consistently and network in the industry"]', 'Variable', 'No standardized salary — earnings vary substantially by projects, role size, industry and career stage.', '["No standardized entrance exam; premier institutes (e.g., NSD, FTII) hold audition/interview-based admissions"]', '[{"title": "Acting Fundamentals", "description": "Learn technique through classes or workshops."}, {"title": "Stage/Theatre Practice", "description": "Gain experience performing live."}, {"title": "Demo Reel", "description": "Compile recorded performance samples."}, {"title": "Auditioning", "description": "Build audition experience and industry contacts."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('fine-artist', 'Fine Artist', 'Arts', '["Visual composition", "Concept distillation", "Material sensibility"]', '["Art/Design"]', '["Creating visually", "Working independently"]', 'Create original visual artwork as a form of personal and creative expression.', '["B.F.A. in Fine Arts (optional but common)"]', '["Build technical skill across mediums", "Develop a personal artistic style", "Exhibit work publicly or online", "Build a body of work and audience"]', 'Variable', 'No standardized salary — income depends heavily on commissions, exhibitions, sales, teaching and freelance work.', '["Institute-specific entrance exams and portfolio review for B.F.A. admission"]', '[{"title": "Technical Skill Building", "description": "Practice drawing, painting, or chosen medium."}, {"title": "Style Development", "description": "Explore and refine a personal artistic voice."}, {"title": "Exhibiting Work", "description": "Share work through shows or online platforms."}, {"title": "Portfolio Building", "description": "Compile a cohesive body of work."}]');
INSERT INTO career_paths (id, name, domain, skills, subjects, work_style, description, education, paths, growth, salary_range, entrance, roadmap_sequence)
VALUES ('architect', 'Architect', 'Arts', '["Spatial reasoning", "Structural constraint-solving", "Visual composition"]', '["Physics", "Art/Design"]', '["Creating visually", "Structured problem solving"]', 'Design buildings and spaces that balance function, safety, and aesthetics.', '["B.Arch (5-year professional degree)", "Council of Architecture registration to practice in India"]', '["Clear an architecture entrance exam (e.g., NATA in India)", "Complete B.Arch degree", "Complete mandatory internship", "Register with the Council of Architecture"]', 'High', '₹4.2–50 LPA', '["NATA (National Aptitude Test in Architecture) or JEE Main Paper 2 for B.Arch admission"]', '[{"title": "Entrance Exam Prep", "description": "Prepare for the architecture entrance examination."}, {"title": "Design Fundamentals", "description": "Learn spatial design and drafting basics."}, {"title": "Studio Projects", "description": "Complete design studio coursework."}, {"title": "Internship & Registration", "description": "Complete internship and register to practice."}]');